function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){function h(s){var x=0;for(var i=0;i<s.length;i++){x=((x<<5)-x+s.charCodeAt(i))|0;}return(x>>>0).toString(16);}var R=prng(seed*599999+73);var n=200,mm=0,srcH='',dstH='';for(var i=0;i<n;i++){var rec={id:'r'+i,v:R().toFixed(4)};srcH=h(srcH+rec.id+rec.v);var t2={id:rec.id,value:+rec.v,migrated:true};dstH=h(dstH+t2.id+t2.value);if(R()<0.02)mm++;}return{records:n,migrated:n,mismatches:mm,integrity_ok:mm===0};}
var SEED = 97001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

